import numpy as np

def normalize(x):
    x = np.asarray(x, dtype=float)
    lo, hi = np.nanmin(x), np.nanmax(x)
    if hi == lo:
        return np.zeros_like(x)
    return (x - lo) / (hi - lo)

import numpy as np

def batch_sums(x, size=4):
    out = []
    for i in range(0, len(x), size):
        out.append(x[i:i + size].sum())
    return out

import numpy as np

def pct_rank(x):
    x = np.asarray(x, dtype=float)
    order = x.argsort().argsort()
    return order / (len(x) - 1) * 100 if len(x) > 1 else np.zeros_like(x)

import pandas as pd

def impute(df):
    report = df.isna().sum()
    for col in df.columns:
        if df[col].dtype.kind in 'fi':
            df[col] = df[col].fillna(df[col].median())
        else:
            mode = df[col].mode()
            df[col] = df[col].fillna(mode.iloc[0] if not mode.empty else 'unknown')
    return df, report[report > 0]

